    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    hr = next((r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg), None)
    if hr is not None:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, grid[hr][0])]
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        if lo > hr:
            shift = (hr + 1 - lo) if lo > hr + 1 else 0
        else:
            shift = (hr - 1 - hi) if hi < hr - 1 else 0
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r + shift][c] = grid[r][c]
        if lo > hr:
            edge = hi + shift + 1 if shift else lo - 1
        else:
            edge = lo + shift - 1 if shift else lo - 1
        if 0 <= edge < h:
            out[edge] = [8] * w
    else:
        vc = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg)
