        left, right = min(c for r, c in pts), max(c for r, c in pts)
        shift = (vc - 1 - right) if right < vc else (vc + 1 - left)
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r][c + shift] = grid[r][c]
        edge = (left + shift - 1) if right < vc else (right + shift + 1)
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
